import {TILE_NAMES} from './display-model.js';

// Original artwork: traditional carved markings in a consistent portrait ratio.
const numerals=['一','二','三','四','五','六','七','八','九'];
const ink='#15233e',red='#a51f32',blue='#16475b',green='#276928';
const dots={1:[[50,65]],2:[[50,32],[50,98]],3:[[25,28],[50,65],[75,102]],4:[[27,31],[73,31],[27,99],[73,99]],5:[[25,28],[75,28],[50,65],[25,102],[75,102]],6:[[27,26],[73,26],[27,65],[73,65],[27,104],[73,104]],7:[[23,23],[50,38],[77,23],[27,76],[73,76],[27,110],[73,110]],8:[[27,21],[73,21],[27,51],[73,51],[27,81],[73,81],[27,111],[73,111]],9:[[24,24],[50,24],[76,24],[24,66],[50,66],[76,66],[24,108],[50,108],[76,108]]};
const bamboo={...dots,2:[[29,65],[71,65]],3:[[50,31],[27,98],[73,98]],4:[[28,33],[72,33],[28,99],[72,99]],5:[[25,29],[75,29],[50,65],[25,102],[75,102]],6:[[25,34],[50,34],[75,34],[25,100],[50,100],[75,100]],8:[[20,32],[40,32],[60,32],[80,32],[20,101],[40,101],[60,101],[80,101]]};
function circle(x,y,r,color){return `<g stroke="${color}" fill="none"><circle cx="${x}" cy="${y}" r="${r}" stroke-width="2.8"/><circle cx="${x}" cy="${y}" r="${r*.67}" stroke-width="1.2"/><circle cx="${x}" cy="${y}" r="${r*.3}" stroke-width="2"/>${Array.from({length:8},(_,i)=>{const a=i*Math.PI/4;return `<path d="M${x+Math.cos(a)*r*.77} ${y+Math.sin(a)*r*.77}l${Math.cos(a)*r*.16} ${Math.sin(a)*r*.16}" stroke-width="1.2"/>`;}).join('')}</g>`;}
function stalk(x,y,h,color){return `<g transform="translate(${x} ${y})" fill="${color}"><path d="M-4 -${h/2}Q0 -${h/2+3} 4 -${h/2}L3 ${h/2}Q0 ${h/2+3} -4 ${h/2}Z"/><path d="M-6 -${h/2-3}Q0 -${h/2+1} 6 -${h/2-3}M-5 0Q0 -2 5 0M-6 ${h/2-3}Q0 ${h/2+1} 6 ${h/2-3}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round"/><path d="M-1 -${h/2-4}L-1 -3M-1 4L-1 ${h/2-4}" fill="none" stroke="#d0e0bf" stroke-width="1" opacity=".8"/></g>`;}
export function tileArt(type){
 const rank=type%9+1;let body='';
 if(type===34)body=`<rect x="3" y="3" width="94" height="126" rx="8" fill="url(#jade)"/><rect x="10" y="10" width="80" height="112" rx="5" fill="none" stroke="#8dc2a1" stroke-width="1" opacity=".5"/><path d="M17 16H83V116H17Z" fill="none" stroke="#126044" opacity=".5"/><g stroke="#b0d5b3" opacity=".13">${Array.from({length:13},(_,i)=>`<path d="M${14+i*6} 17V115"/>`).join('')}</g>`;
 else if(type<9)body=`<text x="50" y="49" fill="${ink}" stroke="${ink}" font-size="53">${numerals[rank-1]}</text><text x="50" y="119" fill="${red}" stroke="${red}" font-size="67">萬</text>`;
 else if(type<18){
  if(rank===1)body=circle(50,66,35,green)+circle(50,66,22,blue)+`<circle cx="50" cy="66" r="9" fill="${red}"/><path d="M50 52V80M36 66H64" stroke="#f1d8b6" stroke-width="1"/>`;
  else body=dots[rank].map(([x,y],i)=>circle(x,y,rank===2?22:rank===3?15:rank===4||rank===5?14:rank===6?13:rank===9?10:11,rank===2?blue:rank===3?[blue,red,green][i]:rank===5&&i===2?red:rank===7&&i<3?red:rank===9?[blue,red,green][Math.floor(i/3)]:green)).join('');
 }
 else if(type===18)body=`<g fill="${green}" stroke="${green}" stroke-linejoin="round"><path d="M41 33C27 23 30 13 41 13C51 12 57 21 55 29L68 35L54 38C59 49 76 51 79 65C84 84 66 98 47 97L28 120L23 116L34 96L17 110L13 105L29 87C22 67 33 47 41 33Z" stroke-width="1.2"/><path d="M42 44C63 46 74 65 65 80C58 90 40 88 32 78C34 64 39 54 42 44Z" fill="#e4e8c8"/><path d="M43 51C60 54 68 67 61 77L36 76Z" fill="${blue}"/><path d="M42 58L60 68M39 65L58 75M37 72L49 79" stroke="#c4d3b4" fill="none" stroke-width="1.4"/><path d="M44 91L48 111L58 115M58 91L64 104L74 105" fill="none" stroke-width="2.8"/><path d="M35 19L28 15L31 22" fill="${red}" stroke="${red}"/><path d="M53 27L67 30L54 33" fill="${red}" stroke="${red}"/><circle cx="44" cy="23" r="4" fill="#eee5c8" stroke="none"/><circle cx="45" cy="23" r="2" fill="${ink}" stroke="none"/></g>`;
 else if(type<27)body=bamboo[rank].map(([x,y],i)=>stalk(x,y,rank===2?68:rank===3?39:rank>=7?23:36,rank===5&&i===2||rank===7&&i<3?red:green)).join('');
 else if(type===31)body=`<rect x="21" y="14" width="58" height="105" rx="2" fill="none" stroke="${blue}" stroke-width="4"/><rect x="28" y="21" width="44" height="91" fill="none" stroke="${blue}" stroke-width="1.4"/><path d="M21 30L29 23M21 46L29 39M21 62L29 55M21 78L29 71M21 94L29 87M21 110L29 103M72 30L79 23M72 46L79 39M72 62L79 55M72 78L79 71M72 94L79 87M72 110L79 103" stroke="${blue}" stroke-width="1.5"/>`;
 else body=`<text x="50" y="98" fill="${type===33?red:type===32?green:ink}" font-size="87">${type===27?'東':TILE_NAMES[type]}</text>`;
 return `<svg viewBox="0 0 100 132" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="jade" x2="1" y2="1"><stop stop-color="#267e5a"/><stop offset=".5" stop-color="#0e573e"/><stop offset="1" stop-color="#378861"/></linearGradient><filter id="carved" x="-10%" y="-10%" width="120%" height="120%"><feDropShadow dx="0" dy=".65" stdDeviation=".25" flood-color="#ffffff" flood-opacity=".9"/></filter></defs><g text-anchor="middle" font-family="STKaiti,Kaiti SC,KaiTi,Songti SC,serif" font-weight="900" stroke-width=".65" filter="url(#carved)">${body}</g></svg>`;
}
